#pragma once

#include "ExecutorService.h"

#include <cstddef>
#include <functional>
#include <future>
#include <memory>
#include <thread>
#include <utility>

// java.util.concurrent.ForkJoinPool 桩。
// 薄壳包装一个内部 ExecutorService（不实现工作窃取，桩级语义等价于普通线程池）。
// commonPool() 返回进程级静态实例（刻意泄漏、永不销毁，避免进程退出时 join 问题）。
class ForkJoinPool : public Executor {
public:
    // 默认构造：并行度取硬件并发数
    ForkJoinPool();
    explicit ForkJoinPool(std::size_t parallelism);
    ~ForkJoinPool() override = default;

    // 进程级公共池（对应 Java ForkJoinPool.commonPool()）
    static ForkJoinPool* commonPool();
    // 公共池并行度：硬件并发数，至少为 1
    static int getCommonPoolParallelism();

    // 提交无返回值任务（实现 Executor 接口）
    void execute(std::function<void()> command) override;

    // 提交带返回值任务（对应 Java Callable），模板方法必须在头文件实现
    template<typename T>
    std::shared_ptr<std::future<T>> submit(std::function<T()> task) {
        return pool_.submit<T>(std::move(task));
    }

    // 停止接收新任务（对 commonPool 调用需谨慎，与 Java 语义一致）
    void shutdown();

private:
    ExecutorService pool_;  // 内部实际承载任务的线程池
};

cpp_code:
#include "ForkJoinPool.h"

ForkJoinPool::ForkJoinPool()
    : pool_(static_cast<std::size_t>(getCommonPoolParallelism())) {}

ForkJoinPool::ForkJoinPool(std::size_t parallelism)
    : pool_(parallelism == 0 ? 1 : parallelism) {}

ForkJoinPool* ForkJoinPool::commonPool() {
    // 进程级单例，刻意不释放：避免静态析构阶段工作线程 join 的时序问题
    static ForkJoinPool* pool = new ForkJoinPool();
    return pool;
}

int ForkJoinPool::getCommonPoolParallelism() {
    unsigned hc = std::thread::hardware_concurrency();
    return static_cast<int>(hc == 0 ? 1 : hc);
}

void ForkJoinPool::execute(std::function<void()> command) {
    pool_.execute(std::move(command));
}

void ForkJoinPool::shutdown() {
    pool_.shutdown();
}
